// C ABI boundary. Pointers come from the native host (Swift/C#); validity is their
// responsibility.
#![allow(clippy::not_unsafe_ptr_arg_deref)]

//! The stable C ABI the native UI links (committed `dontspeak.h`, generated by
//! cbindgen). The app is an informational menu-bar + health panel, so this
//! surface is small and HANDLE-FREE (no opaque handle type): read-only probes,
//! the in-process engine lifecycle (start/stop/reload), a few session controls
//! (mute, TTS provider, locale), shared UI constants/formatters/i18n lookups,
//! and the string free. The rich control surface
//! (voice/engine/language/rate/toggles/downloads) lives in DontSpeak.

use std::ffi::{CString, c_char};
use std::panic::{AssertUnwindSafe, catch_unwind};

use crate::{engine, models};

// Every panic reachable from this file's `extern "C"` fns is meant to be caught by
// `guard_val`/`guard_str` below and turned into a safe default — but `catch_unwind` is a
// documented no-op when the crate is compiled with `panic = "abort"` (the process aborts
// before unwinding ever starts), which silently voids this entire safety boundary for
// whatever native app has this staticlib/cdylib loaded in-process. The workspace's
// `release-ffi` profile (rust/Cargo.toml) exists specifically to override the default
// `release` profile's `panic = "abort"` back to `"unwind"` for this crate — every build of
// ds-core as a cdylib/staticlib for a hosting native app MUST use it (see
// apps/macos/build.sh and apps/windows/installer/build-common.ps1). Fail the build loudly
// instead of silently shipping a host process that aborts on any FFI-reachable panic.
#[cfg(panic = "abort")]
compile_error!(
    "ds-core must not be built with panic=\"abort\" -- its extern \"C\" boundary relies on \
     catch_unwind (see guard_val/guard_str below), which is a documented no-op under an abort \
     strategy and would let any panic reachable from an extern \"C\" fn abort the whole hosting \
     process. Build with `cargo build --profile release-ffi -p ds-core` (or any profile with \
     panic=\"unwind\") instead of the default `release` profile."
);

// ── In-process engine host ───────────────────────────────────────────────────
// The lifecycle state lives in [`crate::host`] (the ONE owner, kept out of this boundary so
// a stray second start can't spawn a competing engine); these C entry points are thin
// adapters returning the u8 the committed `dontspeak.h` documents.

/// Start the engine on a background thread if not already running. Returns 1 if
/// it is now running (started or already up), 0 on failure.
#[unsafe(no_mangle)]
pub extern "C" fn ds_engine_start() -> u8 {
    guard_val(0, || crate::host::engine_start() as u8)
}

/// Stop the engine (clear the run flag, join the thread). Returns 1 if an engine
/// was running, 0 if none. Safe to call on quit.
#[unsafe(no_mangle)]
pub extern "C" fn ds_engine_stop() -> u8 {
    guard_val(0, || crate::host::engine_stop() as u8)
}

/// Ask the running engine to re-read its config (no restart). Returns 1 if an
/// engine is running, else 0.
#[unsafe(no_mangle)]
pub extern "C" fn ds_engine_reload() -> u8 {
    guard_val(0, || crate::host::engine_reload() as u8)
}

/// Set global MUTE (the tray "Mute" checkbox). `on != 0` mutes — playback keeps draining,
/// only the audio is silenced. Sent to the running engine over IPC (the same channel the
/// status read uses); returns 1 if the request was delivered, 0 if the engine is down.
#[unsafe(no_mangle)]
pub extern "C" fn ds_set_muted(on: u8) -> u8 {
    guard_val(0, || {
        let Some(paths) = ds_config::Paths::resolve() else {
            return 0;
        };
        match ds_ipc::request(
            &paths.engine_sock,
            &ds_ipc::Request::SetMuted { on: on != 0 },
        ) {
            Ok(ds_ipc::Response::Done) => 1,
            _ => 0,
        }
    })
}

/// Open the OS's system-voice settings page (macOS Spoken Content / Windows Speech / TODO Linux).
/// Cross-platform seam for the UI "Manage voices" button. Returns 1 if launched, 0 otherwise. HANDLE-FREE.
#[unsafe(no_mangle)]
pub extern "C" fn ds_open_voice_settings() -> u8 {
    guard_val(0, || ds_tts::system::open_voice_settings() as u8)
}

/// Run `f`, returning its documented failure default on panic. Panics must not
/// cross the FFI boundary.
fn guard_val<T>(default: T, f: impl FnOnce() -> T) -> T {
    catch_unwind(AssertUnwindSafe(f)).unwrap_or(default)
}

/// Like [`guard_val`] but for the string-returning FFI fns below: `default` is a static
/// fallback string, turned into a heap `CString` only on the (rare) panic path. Using
/// `guard_val(to_cstring(default), ...)` instead would eagerly allocate that fallback
/// `CString` on EVERY call (the overwhelmingly common non-panicking path included), then
/// silently leak it: `Result::unwrap_or` drops the unused `Ok`/`Err` value, and dropping a
/// `*mut c_char` runs no destructor, so the eagerly-allocated bytes are never freed. Only
/// building the fallback in the panic branch (via `unwrap_or_else`) avoids that leak.
fn guard_str(default: &'static str, f: impl FnOnce() -> *mut c_char) -> *mut c_char {
    catch_unwind(AssertUnwindSafe(f)).unwrap_or_else(|_| to_cstring(default))
}

/// Allocate a Rust string into a heap C string the caller frees with
/// `ds_string_free`. An interior NUL (impossible in our data) → "".
fn to_cstring(s: impl Into<Vec<u8>>) -> *mut c_char {
    match CString::new(s) {
        Ok(c) => c.into_raw(),
        Err(_) => CString::new("").unwrap().into_raw(),
    }
}

/// Read an inbound C string into an owned String (empty if NULL or invalid UTF-8).
fn cstr_or_empty(p: *const c_char) -> String {
    cstr_or(p, "")
}

/// Read an inbound C string, substituting `default` for a NULL pointer OR invalid
/// UTF-8 (a VALID string — including an empty one — is returned as-is). The one
/// place the NULL/bad-UTF-8 fallback is decided; each caller passes its own
/// intended default explicitly.
fn cstr_or(p: *const c_char, default: &str) -> String {
    if p.is_null() {
        return default.to_string();
    }
    // SAFETY: `p` is non-null (checked above); per this C ABI's contract the caller
    // passes a NUL-terminated string that stays valid for the call, and the borrowed
    // CStr is copied into an owned String before returning.
    unsafe { std::ffi::CStr::from_ptr(p) }
        .to_str()
        .unwrap_or(default)
        .to_string()
}

