/// Set the TTS execution provider for this session: `provider` is "cpu" | "cuda" |
/// "coreml" | "ane" | "auto" (NULL/unknown → "auto"). The engine restarts the warm Kokoro child on
/// the new provider and resets its TTS stats (only if the active provider actually
/// changed). Returns 1 if the request reached the engine, else 0. The new provider
/// + fresh stats then show up via `ds_model_status_json`.
#[unsafe(no_mangle)]
pub extern "C" fn ds_set_provider(provider: *const c_char) -> u8 {
    guard_val(0, || {
        // NULL/invalid-UTF-8 → "auto" (let the engine pick the provider).
        let provider = cstr_or(provider, "auto");
        let Some(paths) = ds_config::Paths::resolve() else {
            return 0;
        };
        match ds_ipc::request(
            &paths.engine_sock,
            &ds_ipc::Request::SetProvider { provider },
        ) {
            Ok(ds_ipc::Response::Done) => 1,
            _ => 0,
        }
    })
}

/// Free a `char*` returned by any ds_* function. NULL is a no-op.
#[unsafe(no_mangle)]
pub extern "C" fn ds_string_free(s: *mut c_char) {
    guard_val((), || {
        if !s.is_null() {
            // SAFETY: per `ds_string_free`'s contract, `s` is a pointer previously
            // returned by `to_cstring` (CString::into_raw) and not yet freed — from_raw
            // reclaims that exact allocation exactly once; NULL was screened out above.
            unsafe { drop(CString::from_raw(s)) };
        }
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The new FFI-boundary function itself, not a duplicate of `ds-model`'s own httpmock unit
    /// tests for `check_for_update_at`: goes through the real `ds_update_check_json_at` seam
    /// (same `guard_str`/`to_cstring` marshaling `ds_update_check_json` uses), pointed at a
    /// mock server so it never touches the real GitHub API on `cargo test`.
    #[test]
    fn ds_update_check_json_at_reads_a_mocked_release_through_the_real_ffi_path() {
        let server = httpmock::MockServer::start();
        let mock = server.mock(|when, then| {
            when.method(httpmock::Method::GET)
                .path("/repos/delllusional/DontSpeak/releases/latest");
            then.status(200).json_body(serde_json::json!({
                "tag_name": "v9.9.9",
                "html_url": "https://github.com/delllusional/DontSpeak/releases/tag/v9.9.9",
            }));
        });

        let ptr = ds_update_check_json_at(&server.base_url());
        // SAFETY: `ptr` was just returned by ds_update_check_json_at, which always
        // yields a non-null, NUL-terminated C string (guard_str/to_cstring); it is
        // freed only after this read, via ds_string_free below.
        let json = unsafe { std::ffi::CStr::from_ptr(ptr) }
            .to_str()
            .unwrap()
            .to_owned();
        ds_string_free(ptr);
        mock.assert();

        let v: serde_json::Value = serde_json::from_str(&json).unwrap();
        assert_eq!(v["update_available"], true);
        assert_eq!(v["latest_version"], "9.9.9");
    }

    /// A failing endpoint must degrade to `"{}"`, never propagate an error to the caller.
    #[test]
    fn ds_update_check_json_at_degrades_to_empty_object_on_a_failing_endpoint() {
        let server = httpmock::MockServer::start();
        let mock = server.mock(|when, then| {
            when.method(httpmock::Method::GET)
                .path("/repos/delllusional/DontSpeak/releases/latest");
            then.status(404);
        });

        let ptr = ds_update_check_json_at(&server.base_url());
        // SAFETY: `ptr` was just returned by ds_update_check_json_at, which always
        // yields a non-null, NUL-terminated C string (guard_str/to_cstring); it is
        // freed only after this read, via ds_string_free below.
        let json = unsafe { std::ffi::CStr::from_ptr(ptr) }
            .to_str()
            .unwrap()
            .to_owned();
        ds_string_free(ptr);
        mock.assert();

        assert_eq!(json, "{}");
    }

    /// End-to-end: the UI tool catalog the hosts read (`ds_tools_json`) enriches EVERY param
    /// with a `detail` string, and constraint params carry the shared localized qualifier — so
    /// no host has to rebuild it. Guards the FFI enrichment, not just the formatter helper.
    #[test]
    fn ds_tools_json_enriches_every_param_with_detail() {
        let ptr = ds_tools_json();
        // SAFETY: `ptr` was just returned by ds_tools_json, which always yields a
        // non-null, NUL-terminated C string (guard_str/to_cstring); it is freed only
        // after this read, via ds_string_free below.
        let json = unsafe { std::ffi::CStr::from_ptr(ptr) }
            .to_str()
            .unwrap()
            .to_owned();
        ds_string_free(ptr);

        let catalog: serde_json::Value = serde_json::from_str(&json).unwrap();
        let tools = catalog.as_array().expect("catalog is an array");
        let mut saw_enum = false;
        for tool in tools {
            for param in tool["params"].as_array().unwrap_or(&Vec::new()) {
                // Every param gets the key (even when empty) so hosts read it unconditionally.
                let detail = param
                    .get("detail")
                    .and_then(|d| d.as_str())
                    .expect("param has a detail field");
                // A param with an `enum` MUST surface the localized "one of: …" qualifier.
                if param
                    .get("enum")
                    .and_then(|e| e.as_array())
                    .is_some_and(|v| !v.is_empty())
                {
                    saw_enum = true;
                    assert!(
                        detail.starts_with("one of: "),
                        "enum param {} → {detail:?}",
                        param["name"]
                    );
                }
            }
        }
        assert!(saw_enum, "catalog has at least one enum param to qualify");
    }
}
